import { GenericMap, Key, MergeKey, StringDict } from './def';
import { BaseReflector } from './base-reflector';
import { ModernDecorators } from './def-modern';
import {
  DecoratorMetadataObject,
  ensureSymbolMetadata,
  getRequiredMetadataObject,
  getRegistryTarget,
} from './utility/modern-decorator-targets';

type PropertyKey = string | symbol;
type DecoratedClass = abstract new (...args: any[]) => any;
type DecoratedCallable = (...args: any[]) => any;

type DecoratorContext =
  | ClassDecoratorContext
  | ClassFieldDecoratorContext
  | ClassMethodDecoratorContext
  | ClassGetterDecoratorContext
  | ClassSetterDecoratorContext
  | ClassAccessorDecoratorContext;

type ValueContextPair =
  | [DecoratedClass, ClassDecoratorContext]
  | [undefined, ClassFieldDecoratorContext]
  | [DecoratedCallable, ClassMethodDecoratorContext]
  | [DecoratedCallable, ClassGetterDecoratorContext]
  | [DecoratedCallable, ClassSetterDecoratorContext]
  | [
      { get?: () => unknown; set?: (value: unknown) => void },
      ClassAccessorDecoratorContext,
    ];

function isDecoratorContext(value: unknown): value is DecoratorContext {
  return (
    !!value &&
    typeof value === 'object' &&
    'kind' in value &&
    typeof (value as { kind?: unknown }).kind === 'string'
  );
}

ensureSymbolMetadata();

export class Reflector<
  M extends StringDict,
  AM extends StringDict,
> extends BaseReflector<M, AM, DecoratorContext, ModernDecorators> {
  protected resolveDecoratorMetadataTarget(context: DecoratorContext) {
    const metadata = getRequiredMetadataObject(context);
    return {
      target: getRegistryTarget(
        metadata,
        context.kind === 'class' ? undefined : context.static,
        context.kind === 'class' ? undefined : (context.name as PropertyKey),
      ),
      key:
        context.kind === 'class'
          ? undefined
          : (context.name as string | symbol | undefined),
    };
  }

  protected resolveKeysIndexContext(context: DecoratorContext) {
    if (context.kind === 'class' || context.name === undefined) {
      return undefined;
    }

    return { ...context, kind: 'class' } as DecoratorContext;
  }

  protected resolveIndexedKey(context: DecoratorContext) {
    return context.kind === 'class'
      ? undefined
      : (context.name as string | symbol | undefined);
  }

  protected createDecorator<
    K extends MergeKey<M, AM>,
    IK extends Key<AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(
    metadataKey: K,
    metadataValueFun: (oldValue: GM[K]) => GM[K],
    keysIndexMeta?: IK,
  ): ModernDecorators {
    return ((...args: ValueContextPair) => {
      const context = args[1];
      if (!isDecoratorContext(context)) {
        throw new TypeError(
          'typed-reflector/modern decorators can only be used with standard decorators.',
        );
      }

      this.applyMetadataTransform<K, GM>(
        metadataKey,
        metadataValueFun,
        context,
        keysIndexMeta,
      );

      return args[0];
    }) as unknown as ModernDecorators;
  }
}

export { Reflector as MetadataSetter };
export { ensureSymbolMetadata };
export type { ReflectorOptions } from './base-reflector';
export type { DecoratorMetadataObject };
