import {
  ArrayValue,
  ArrayValueMap,
  GenericMap,
  Key,
  MapValue,
  MergeKey,
  StringDict,
} from './def';
import { GlobalRegistry, MetadataRegistry } from './registry';
import { getClass, isClass } from './utility/utility';
import {
  getClassMetadataObject,
  getRegistryTarget,
} from './utility/modern-decorator-targets';

export interface ReflectorOptions {
  registry?: MetadataRegistry;
}

export abstract class BaseReflector<
  M extends StringDict,
  AM extends StringDict,
  Context,
  DecoratorOutput,
> {
  readonly registry: MetadataRegistry;

  constructor(options: ReflectorOptions = {}) {
    this.registry = options.registry || GlobalRegistry;
  }

  protected abstract createDecorator<
    K extends MergeKey<M, AM>,
    IK extends Key<AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(
    metadataKey: K,
    metadataValueFun: (oldValue: GM[K]) => GM[K],
    keysIndexMeta?: IK,
  ): DecoratorOutput;

  protected abstract resolveDecoratorMetadataTarget(context: Context): {
    target: object;
    key?: string | symbol;
  };

  protected abstract resolveKeysIndexContext(
    context: Context,
  ): Context | undefined;

  protected abstract resolveIndexedKey(
    context: Context,
  ): string | symbol | undefined;

  protected prepareMetadataValue<T>(metadataValue: T): T {
    if (Array.isArray(metadataValue)) {
      return metadataValue.slice() as T;
    }

    return metadataValue;
  }

  protected readMetadataInDecorator<
    K extends MergeKey<M, AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(metadataKey: K, context: Context): GM[K] {
    const target = this.resolveDecoratorMetadataTarget(context);
    return (
      target.key !== undefined
        ? this.registry.getMetadata(metadataKey, target.target, target.key)
        : this.registry.getMetadata(metadataKey, target.target)
    ) as GM[K];
  }

  protected writeMetadataInDecorator<
    K extends MergeKey<M, AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(metadataKey: K, metadataValue: GM[K], context: Context): void {
    const target = this.resolveDecoratorMetadataTarget(context);
    if (target.key !== undefined) {
      this.registry.defineMetadata(
        metadataKey,
        metadataValue,
        target.target,
        target.key,
      );
      return;
    }

    this.registry.defineMetadata(metadataKey, metadataValue, target.target);
  }

  protected appendIndexedKey<IK extends Key<AM>>(
    metadataKey: IK,
    context: Context,
  ): void {
    const indexedKey = this.resolveIndexedKey(context);
    const keysContext = this.resolveKeysIndexContext(context);
    if (indexedKey === undefined || !keysContext) {
      return;
    }

    this.applyMetadataTransform<IK, ArrayValueMap<AM>>(
      metadataKey,
      (currentValue) => {
        const nextValue = currentValue || [];
        if (!nextValue.includes(indexedKey as any)) {
          nextValue.push(indexedKey as any);
        }
        return nextValue;
      },
      keysContext,
    );
  }

  protected applyMetadataTransform<
    K extends MergeKey<M, AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(
    metadataKey: K,
    metadataValueFun: (oldValue: GM[K]) => GM[K],
    context: Context,
    keysIndexMeta?: Key<AM>,
  ) {
    const oldValue = this.prepareMetadataValue(
      this.readMetadataInDecorator<K, GM>(metadataKey, context),
    );
    const newValue = metadataValueFun(oldValue);
    this.writeMetadataInDecorator<K, GM>(metadataKey, newValue, context);

    if (keysIndexMeta !== undefined) {
      this.appendIndexedKey(keysIndexMeta, context);
    }
  }

  protected setParameterMetadata<K extends Key<AM>>(
    metadataKey: K,
    metadataValue: AM[K],
    context: Context,
    index: number,
  ) {
    const oldValue = this.prepareMetadataValue(
      this.readMetadataInDecorator<K, ArrayValueMap<AM>>(metadataKey, context),
    );
    const nextValue = oldValue || [];
    nextValue[index] = metadataValue;
    this.writeMetadataInDecorator<K, ArrayValueMap<AM>>(
      metadataKey,
      nextValue,
      context,
    );
  }

  private getClassMetadataTargets(instance: any) {
    const instanceClass = getClass(instance);
    const targets: object[] = [instanceClass];
    const modernMetadata = getClassMetadataObject(instanceClass);
    if (modernMetadata) {
      targets.unshift(getRegistryTarget(modernMetadata, undefined));
    }

    return Array.from(new Set(targets));
  }

  private getMemberMetadataTargets(instance: any, key: string | symbol) {
    const instanceClass = getClass(instance);
    const isPrototypeTarget =
      !isClass(instance) && instance === instanceClass.prototype;
    const prototypeTarget = isClass(instance)
      ? instanceClass.prototype
      : isPrototypeTarget
        ? instance
        : Object.getPrototypeOf(instance);
    const legacyTargets: object[] = isClass(instance)
      ? [instanceClass, prototypeTarget]
      : [prototypeTarget, instanceClass];

    const modernMetadata = getClassMetadataObject(instanceClass);
    const modernTargets: object[] = modernMetadata
      ? [
          getRegistryTarget(modernMetadata, isClass(instance), key),
          getRegistryTarget(modernMetadata, !isClass(instance), key),
        ]
      : [];

    return Array.from(new Set([...modernTargets, ...legacyTargets]));
  }

  transform<
    K extends MergeKey<M, AM>,
    IK extends Key<AM>,
    GM extends Record<MergeKey<M, AM>, any> = GenericMap<M, AM>,
  >(
    metadataKey: K,
    metadataValueFun: (oldValue: GM[K]) => GM[K],
    keysIndexMeta?: IK,
  ): DecoratorOutput {
    return this.createDecorator<K, IK, GM>(
      metadataKey,
      metadataValueFun,
      keysIndexMeta,
    );
  }

  set<K extends MergeKey<M, AM>, IK extends Key<AM>>(
    metadataKey: K,
    metadataValue: GenericMap<M, AM>[K],
    keysIndexMeta?: IK,
  ) {
    return this.transform<K, IK>(
      metadataKey,
      () => metadataValue,
      keysIndexMeta,
    );
  }

  append<K extends Key<AM>, IK extends Key<AM>>(
    metadataKey: K,
    metadataValue: AM[K],
    keysIndexMeta?: IK,
  ) {
    return this.transform<K, IK, ArrayValueMap<AM>>(
      metadataKey,
      (currentValue) => {
        const nextValue = currentValue || [];
        nextValue.push(metadataValue);
        return nextValue;
      },
      keysIndexMeta,
    );
  }

  appendUnique<K extends Key<AM>, IK extends Key<AM>>(
    metadataKey: K,
    metadataValue: AM[K],
    keysIndexMeta?: IK,
  ) {
    return this.transform<K, IK, ArrayValueMap<AM>>(
      metadataKey,
      (currentValue) => {
        const nextValue = currentValue || [];
        if (!nextValue.includes(metadataValue)) {
          nextValue.push(metadataValue);
        }
        return nextValue;
      },
      keysIndexMeta,
    );
  }

  concat<K extends Key<AM>, IK extends Key<AM>>(
    metadataKey: K,
    metadataValue: ArrayValueMap<AM>[K],
    keysIndexMeta?: IK,
  ) {
    return this.transform<K, IK, ArrayValueMap<AM>>(
      metadataKey,
      (currentValue) => (currentValue || []).concat(metadataValue),
      keysIndexMeta,
    );
  }

  get<K extends Key<GenericMap<M, AM>>>(
    metadataKey: K,
    instance: any,
    key?: string | symbol,
  ): MapValue<M, AM, K> {
    const targets =
      key !== undefined
        ? this.getMemberMetadataTargets(instance, key)
        : this.getClassMetadataTargets(instance);

    for (const target of targets) {
      if (
        key !== undefined
          ? this.registry.hasMetadata(metadataKey, target, key)
          : this.registry.hasMetadata(metadataKey, target)
      ) {
        return (
          key !== undefined
            ? this.registry.getMetadata(metadataKey, target, key)
            : this.registry.getMetadata(metadataKey, target)
        ) as MapValue<M, AM, K>;
      }
    }

    return undefined as MapValue<M, AM, K>;
  }

  getArray<K extends Key<AM>>(
    metadataKey: K,
    instance: any,
    key?: string | symbol,
  ): ArrayValue<AM, K> {
    return (this.get(
      metadataKey as unknown as Key<GenericMap<M, AM>>,
      instance,
      key,
    ) || []) as ArrayValue<AM, K>;
  }

  getProperty<K extends Key<AM>, I = any>(
    metadataKey: K,
    instance: I,
    key: keyof I & (string | symbol),
    alternate?: any,
  ): ArrayValue<AM, K> {
    const valueFromClass = this.getArray(metadataKey, instance);
    const valueFromAlternate = alternate
      ? this.getArray(metadataKey, alternate)
      : [];
    const valueFromProperty = this.getArray(metadataKey, instance, key);
    return [
      ...valueFromClass,
      ...valueFromAlternate,
      ...valueFromProperty,
    ] as ArrayValue<AM, K>;
  }
}
