type MetadataKey = string | symbol;
type PropertyKey = string | symbol;
type MetadataBucket = Map<MetadataKey, any>;
const GLOBAL_REGISTRY_KEY = Symbol.for('typed-reflector.global-registry');

interface MetadataStore {
  target: MetadataBucket;
  properties: Map<PropertyKey, MetadataBucket>;
}

function getPropertyBucket(
  store: MetadataStore,
  propertyKey: PropertyKey,
  create: boolean,
) {
  const bucket = store.properties.get(propertyKey);
  if (bucket || !create) {
    return bucket;
  }

  const nextBucket = new Map<MetadataKey, any>();
  store.properties.set(propertyKey, nextBucket);
  return nextBucket;
}

export class MetadataRegistry {
  private readonly store = new WeakMap<object, MetadataStore>();

  private getStore(target: object, create: boolean) {
    const store = this.store.get(target);
    if (store || !create) {
      return store;
    }

    const nextStore: MetadataStore = {
      target: new Map(),
      properties: new Map(),
    };
    this.store.set(target, nextStore);
    return nextStore;
  }

  private getOwnBucket(
    target: object,
    propertyKey?: PropertyKey,
    create = false,
  ) {
    const store = this.getStore(target, create);
    if (!store) {
      return undefined;
    }

    if (propertyKey === undefined) {
      return store.target;
    }

    return getPropertyBucket(store, propertyKey, create);
  }

  private *walkPrototypeChain(target: object) {
    let current: object | null = target;
    while (current) {
      yield current;
      current = Object.getPrototypeOf(current);
    }
  }

  defineMetadata(metadataKey: MetadataKey, value: any, target: object): void;
  defineMetadata(
    metadataKey: MetadataKey,
    value: any,
    target: object,
    propertyKey: PropertyKey,
  ): void;
  defineMetadata(
    metadataKey: MetadataKey,
    value: any,
    target: object,
    propertyKey?: PropertyKey,
  ) {
    const bucket = this.getOwnBucket(target, propertyKey, true);
    bucket!.set(metadataKey, value);
  }

  hasOwnMetadata(metadataKey: MetadataKey, target: object): boolean;
  hasOwnMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey: PropertyKey,
  ): boolean;
  hasOwnMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey?: PropertyKey,
  ) {
    return this.getOwnBucket(target, propertyKey)?.has(metadataKey) ?? false;
  }

  hasMetadata(metadataKey: MetadataKey, target: object): boolean;
  hasMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey: PropertyKey,
  ): boolean;
  hasMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey?: PropertyKey,
  ) {
    for (const current of this.walkPrototypeChain(target)) {
      if (
        this.hasOwnMetadata(metadataKey, current, propertyKey as PropertyKey)
      ) {
        return true;
      }
    }

    return false;
  }

  getOwnMetadata(metadataKey: MetadataKey, target: object): any;
  getOwnMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey: PropertyKey,
  ): any;
  getOwnMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey?: PropertyKey,
  ) {
    return this.getOwnBucket(target, propertyKey)?.get(metadataKey);
  }

  getMetadata(metadataKey: MetadataKey, target: object): any;
  getMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey: PropertyKey,
  ): any;
  getMetadata(
    metadataKey: MetadataKey,
    target: object,
    propertyKey?: PropertyKey,
  ) {
    for (const current of this.walkPrototypeChain(target)) {
      const bucket = this.getOwnBucket(current, propertyKey);
      if (bucket?.has(metadataKey)) {
        return bucket.get(metadataKey);
      }
    }

    return undefined;
  }
}

type GlobalRegistryHost = typeof globalThis & {
  [GLOBAL_REGISTRY_KEY]?: MetadataRegistry;
};

const globalRegistryHost = globalThis as GlobalRegistryHost;

export const GlobalRegistry =
  globalRegistryHost[GLOBAL_REGISTRY_KEY] ||
  (globalRegistryHost[GLOBAL_REGISTRY_KEY] = new MetadataRegistry());
